1	import { memo, useCallback, useEffect, useState, useMemo } from 'react';
2	import {
3	  ReactFlow,
4	  ReactFlowProvider,
5	  Background,
6	  BackgroundVariant,
7	  MiniMap,
8	  Panel,
9	  useNodesState,
10	  useEdgesState,
11	  useReactFlow,
12	  Handle,
13	  Position,
14	  type Node,
15	  type Edge,
16	  type NodeTypes,
17	  type NodeDragHandler,
18	  type NodeMouseHandler,
19	} from '@xyflow/react';
20	import '@xyflow/react/dist/style.css';
21	import { useNavigate, useSearchParams } from 'react-router-dom';
22	import { supabase } from '@/integrations/supabase/client';
23	import { useCmvGraph } from '@/features/financeiro/model/useCmvGraph';
24	import { layoutGraph } from '@/components/producao/configurador/layout';
25	import { toast } from 'sonner';
26	import {
27	  ArrowLeft,
28	  Calculator,
29	  ChefHat,
30	  Package,
31	  DollarSign,
32	  Receipt,
33	  Loader2,
34	} from 'lucide-react';
35	import { Button } from '@/shared/ui/button';
36	import { CmvNodePalette } from './cmv/CmvNodePalette';
37	import { CmvDetailPanel } from './cmv/CmvDetailPanel';
38	import { CmvBottomToolbar } from './cmv/CmvBottomToolbar';
39	
40	// ---------------------------------------------------------------------------
41	// HELPERS
42	// ---------------------------------------------------------------------------
43	
44	const fmt = (v: number | null | undefined): string => {
45	  if (v === null || v === undefined) return 'R$ 0,00';
46	  return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
47	};
48	
49	const STATUS_COLORS: Record<string, string> = {
50	  rascunho: 'bg-zinc-200/80 text-zinc-700 dark:bg-zinc-700 dark:text-zinc-300',
51	  aprovada: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-800/60 dark:text-emerald-300',
52	  obsoleta: 'bg-zinc-200/80 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-500',
53	};
54	
55	// ---------------------------------------------------------------------------
56	// NODE DATA TYPES
57	// ---------------------------------------------------------------------------
58	
59	interface CmvRootNodeData extends Record<string, unknown> {
60	  nome: string;
61	  custo: number | null;
62	  status: string;
63	  kind: string;
64	}
65	
66	interface FichaBaseNodeData extends Record<string, unknown> {
67	  nome: string;
68	  custoUnitario: number;
69	  rendimento: string;
70	  custoTotal: number | null;
71	  rendQty: number;
72	  rendimento_unidade: string;
73	  kind: string;
74	}
75	
76	interface CmvItemNodeData extends Record<string, unknown> {
77	  tipo: string;
78	  quantidade: number;
79	  unidade: string;
80	  custo: number | null;
81	  label: string;
82	  kind: string;
83	  _rawItemId: number;
84	}
85	
86	interface NFNodeData extends Record<string, unknown> {
87	  fornecedor: string;
88	  numero: string | null;
89	  valor: number | null;
90	  kind: string;
91	}
92	
93	// ---------------------------------------------------------------------------
94	// NODE COMPONENTS
95	// ---------------------------------------------------------------------------
96	
97	// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
98	const CmvRootNode = memo(function CmvRootNode({ data }: { data: CmvRootNodeData }) {
99	  return (
100	    <div className="relative px-5 py-4 rounded-2xl border border-[#57715B]/50 bg-[#57715B]/90 backdrop-blur-md text-white min-w-[260px] shadow-2xl shadow-[#57715B]/40">
101	      <div className="flex items-start justify-between mb-2 gap-2">
102	        <div className="flex items-center gap-1.5 opacity-80">
103	          <Calculator size={12} />
104	          <span className="text-[9px] font-bold uppercase tracking-wider">CMV Central</span>
105	        </div>
106	        <span
107	          className={`text-[9px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[data.status] ?? STATUS_COLORS.rascunho}`}
108	        >
109	          {data.status}
110	        </span>
111	      </div>
112	      <h3 className="text-base font-bold truncate leading-tight mb-2">{data.nome}</h3>
113	      <p className="text-2xl font-black tabular-nums">{fmt(data.custo)}</p>
114	      <Handle
115	        type="target"
116	        position={Position.Left}
117	        className="!w-3.5 !h-3.5 !bg-white/60 !border-2 !border-white/30"
118	      />
119	    </div>
120	  );
121	});
122	
123	// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
124	const FichaBaseNode = memo(function FichaBaseNode({ data }: { data: FichaBaseNodeData }) {
125	  const custoUnit = data.rendQty > 0 ? (data.custoTotal ?? 0) / data.rendQty : 0;
126	  return (
127	    <div className="relative px-5 py-4 rounded-2xl border border-amber-500/40 bg-amber-700/80 backdrop-blur-md text-white min-w-[240px] shadow-xl shadow-amber-700/30">
128	      <div className="flex items-center gap-1.5 opacity-80 mb-2">
129	        <ChefHat size={12} />
130	        <span className="text-[9px] font-bold uppercase tracking-wider">Ficha Técnica Base</span>
131	      </div>
132	      <h3 className="text-base font-semibold truncate mb-1">{data.nome}</h3>
133	      <div className="flex items-end justify-between mt-2">
134	        <div>
135	          <p className="text-[9px] opacity-60 leading-none mb-0.5">Custo total</p>
136	          <p className="text-xl font-bold tabular-nums">{fmt(data.custoTotal)}</p>
137	          {data.rendQty > 0 && (
138	            <p className="text-[10px] text-amber-200 mt-1">
139	              {fmt(custoUnit)} / {data.rendimento_unidade}
140	            </p>
141	          )}
142	        </div>
143	        <span className="text-[10px] px-2 py-0.5 bg-white/20 rounded-full">{data.rendimento}</span>
144	      </div>
145	      <Handle
146	        type="source"
147	        position={Position.Right}
148	        className="!w-3 !h-3 !bg-amber-300 !border-2 !border-white"
149	      />
150	    </div>
151	  );
152	});
153	
154	// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
155	const CmvItemNode = memo(function CmvItemNode({
156	  data,
157	  selected,
158	}: {
159	  data: CmvItemNodeData;
160	  selected: boolean;
161	}) {
162	  const isEmb = data.tipo === 'embalagem';
163	  const color = isEmb
164	    ? 'bg-blue-600/80 border-blue-400/40'
165	    : 'bg-orange-700/60 border-dashed border-orange-400/60';
166	  const icon = isEmb ? <Package size={12} /> : <DollarSign size={12} />;
167	  const label = isEmb ? 'Embalagem' : 'Custo avulso';
168	
169	  return (
170	    <div
171	      className={`relative px-4 py-3 rounded-xl border backdrop-blur-md text-zinc-100 min-w-[200px] shadow-lg transition-all duration-150 ${color} ${selected ? 'ring-2 ring-white/40 scale-[1.02]' : 'hover:shadow-xl hover:-translate-y-0.5'}`}
172	    >
173	      <div className="flex items-center gap-1.5 mb-2">
174	        <span className="opacity-80">{icon}</span>
175	        <span className="text-[9px] font-bold uppercase tracking-wider opacity-80">{label}</span>
176	      </div>
177	      <h4 className="text-sm font-semibold truncate mb-1.5">{data.label}</h4>
178	      <div className="flex items-end justify-between">
179	        <span className="text-[11px] text-white/70">
180	          {data.quantidade} {data.unidade}
181	        </span>
182	        <span className="text-base font-bold tabular-nums">{fmt(data.custo)}</span>
183	      </div>
184	      <Handle
185	        type="target"
186	        position={Position.Left}
187	        className="!w-2.5 !h-2.5 !bg-white/40 !border-2 !border-white/20"
188	      />
189	      <Handle
190	        type="source"
191	        position={Position.Right}
192	        className="!w-2.5 !h-2.5 !bg-white/60 !border-2 !border-white/30"
193	      />
194	    </div>
195	  );
196	});
197	
198	// @ts-expect-error ReactFlow NodeProps generic mismatch with our typed data shape
199	const NFNode = memo(function NFNode({ data }: { data: NFNodeData }) {
200	  return (
201	    <div className="px-3 py-2 rounded-lg border border-cyan-400/30 bg-cyan-700/70 backdrop-blur-sm text-white min-w-[160px] shadow-md">
202	      <div className="flex items-center gap-1 mb-1 opacity-70">
203	        <Receipt size={10} />
204	        <span className="text-[9px] font-bold uppercase">Nota Fiscal</span>
205	      </div>
206	      <h4 className="text-[11px] font-semibold truncate">{data.fornecedor ?? 'Fornecedor'}</h4>
207	      {data.numero && <p className="text-[9px] opacity-60">#{data.numero}</p>}
208	      <Handle
209	        type="source"
210	        position={Position.Right}
211	        className="!w-2 !h-2 !bg-cyan-300 !border-2 !border-white"
212	      />
213	    </div>
214	  );
215	});
216	
217	const nodeTypes: NodeTypes = {
218	  cmv: CmvRootNode,
219	  ficha: FichaBaseNode,
220	  cmvItem: CmvItemNode,
221	  nf: NFNode,
222	};
223	
224	// ---------------------------------------------------------------------------
225	// INNER COMPONENT
226	// ---------------------------------------------------------------------------
227	
228	function CmvConfiguratorInner() {
229	  const navigate = useNavigate();
230	  const [searchParams] = useSearchParams();
231	  const cmvIdParam = searchParams.get('focus');
232	  const cmvId = cmvIdParam ? parseInt(cmvIdParam, 10) : null;
233	
234	  const {
235	    loading,
236	    cmv,
237	    fichaData,
238	    items,
239	    embalagens,
240	    nfEmbalagemItems,
241	    positions,
242	    savePosition,
243	    refetch,
244	  } = useCmvGraph(cmvId);
245	
246	  const { fitView } = useReactFlow();
247	  const [nodes, setNodes, onNodesChange] = useNodesState([]);
248	  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
249	  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
250	
251	  const handleNodeClick: NodeMouseHandler = useCallback((_evt, node) => {
252	    setSelectedNodeId(node.id);
253	  }, []);
254	
255	  const handlePaneClick = useCallback(() => {
256	    setSelectedNodeId(null);
257	  }, []);
258	
259	  const { custoFichaUnitario, custoEmbalagens, custoAvulsos, custoTotal } = useMemo(() => {
260	    const fichaUnitario = fichaData
261	      ? (fichaData.custo_calculado ?? 0) / Math.max(1, fichaData.rendimento_quantidade)
262	      : 0;
263	    const embalagensTotal = items
264	      .filter((i) => i.tipo === 'embalagem')
265	      .reduce((s, i) => s + (i.custo_calculado ?? 0), 0);
266	    const avulsosTotal = items
267	      .filter((i) => i.tipo === 'outro')
268	      .reduce((s, i) => s + (i.custo_calculado ?? 0), 0);
269	    const total = cmv?.custo_calculado ?? 0;
270	    return {
271	      custoFichaUnitario: fichaUnitario,
272	      custoEmbalagens: embalagensTotal,
273	      custoAvulsos: avulsosTotal,
274	      custoTotal: total,
275	    };
276	  }, [items, cmv, fichaData]);
277	
278	  const buildGraph = useCallback(() => {
279	    if (!cmv) return;
280	
281	    const newNodes: Node[] = [];
282	    const newEdges: Edge[] = [];
283	    const rootId = `cmv_${cmv.id}`;
284	
285	    newNodes.push({
286	      id: rootId,
287	      type: 'cmv',
288	      data: {
289	        nome: cmv.nome,
290	        custo: cmv.custo_calculado,
291	        status: cmv.status,
292	        kind: 'cmv',
293	      } as CmvRootNodeData,
294	      position: positions.get(rootId) ?? { x: 800, y: 300 },
295	    });
296	
297	    if (fichaData) {
298	      const fId = `ficha_${fichaData.id}`;
299	      const rendQty = fichaData.rendimento_quantidade || 1;
300	      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;
301	
302	      newNodes.push({
303	        id: fId,
304	        type: 'ficha',
305	        data: {
306	          nome: fichaData.nome,
307	          custoUnitario,
308	          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
309	          custoTotal: fichaData.custo_calculado,
310	          rendQty,
311	          rendimento_unidade: fichaData.rendimento_unidade,
312	          kind: 'ficha',
313	        } as FichaBaseNodeData,
314	        position: positions.get(fId) ?? { x: 400, y: 300 },
315	      });
316	
317	      newEdges.push({
318	        id: `e-${fId}-${rootId}`,
319	        source: fId,
320	        target: rootId,
321	        animated: true,
322	        style: { stroke: '#F59E0B', strokeWidth: 3 },
323	      });
324	    }
325	
326	    items.forEach((item, idx) => {
327	      const itemId = `item_${item.id}`;
328	      const label =
329	        item.produtoMaster?.nome ?? item.insumo?.nome ?? item.observacao ?? 'Embalagem';
330	
331	      newNodes.push({
332	        id: itemId,
333	        type: 'cmvItem',
334	        data: {
335	          tipo: item.tipo,
336	          quantidade: item.quantidade,
337	          unidade: item.unidade,
338	          custo: item.custo_calculado,
339	          label,
340	          kind: 'cmvItem',
341	          _rawItemId: item.id,
342	        } as CmvItemNodeData,
343	        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
344	      });
345	
346	      newEdges.push({
347	        id: `e-${itemId}-${rootId}`,
348	        source: itemId,
349	        target: rootId,
350	        style: { stroke: '#52525b', strokeWidth: 2 },
351	      });
352	    });
353	
354	    const addedNotaIds = new Set<number>();
355	    items.forEach((item) => {
356	      if (item.nf_item_id && item.nfItem?.nota_id) {
357	        const notaId = item.nfItem.nota_id;
358	        if (!addedNotaIds.has(notaId)) {
359	          addedNotaIds.add(notaId);
360	          const nfId = `nf_nota_${notaId}`;
361	          newNodes.push({
362	            id: nfId,
363	            type: 'nf',
364	            data: {
365	              fornecedor: item.nfItem.fornecedor ?? 'Fornecedor',
366	              numero: item.nfItem.numero_nota,
367	              valor: null,
368	              kind: 'nf',
369	            } as NFNodeData,
370	            position: positions.get(nfId) ?? { x: 50, y: 50 + addedNotaIds.size * 140 },
371	          });
372	        }
373	
374	        const nfId = `nf_nota_${notaId}`;
375	        const itemId = `item_${item.id}`;
376	        newEdges.push({
377	          id: `e-${nfId}-${itemId}`,
378	          source: nfId,
379	          target: itemId,
380	          style: { stroke: '#22d3ee', strokeWidth: 1.5, strokeDasharray: '4 2' },
381	        });
382	      }
383	    });
384	
385	    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
386	    if (!hasAllPositions && newNodes.length > 0) {
387	      const laid = layoutGraph(newNodes, newEdges, 'LR');
388	      setNodes(laid);
389	    } else {
390	      setNodes(newNodes);
391	    }
392	    setEdges(newEdges);
393	
394	    setTimeout(() => {
395	      fitView({ padding: 0.12, duration: 400 });
396	    }, 80);
397	  }, [cmv, fichaData, items, positions, fitView, setNodes, setEdges]);
398	
399	  useEffect(() => {
400	    if (!loading) buildGraph();
401	  }, [loading, buildGraph]);
402	
403	  const handleNodeDragStop: NodeDragHandler = useCallback(
404	    (_evt, node) => {
405	      if (!node.id.startsWith('nf_nota_')) {
406	        savePosition(node.id, node.position.x, node.position.y);
407	      }
408	    },
409	    [savePosition],
410	  );
411	
412	  const handleAddEmbalagem = useCallback(
413	    async (embId: number) => {
414	      if (!cmvId) return;
415	      const { error } = await supabase.from('cmv_itens').insert({
416	        cmv_id: cmvId,
417	        tipo: 'embalagem',
418	        produto_master_id: embId,
419	        quantidade: 1,
420	        unidade: 'un',
421	        ordem: items.length,
422	      } as Record<string, unknown>);
423	      if (error) {
424	        toast.error(error.message);
425	        return;
426	      }
427	      toast.success('Embalagem adicionada');
428	      await refetch();
429	    },
430	    [cmvId, items.length, refetch],
431	  );
432	
433	  const handleAddAvulso = useCallback(
434	    async (nome: string, valor: number) => {
435	      if (!cmvId) return;
436	      const { error } = await supabase.from('cmv_itens').insert({
437	        cmv_id: cmvId,
438	        tipo: 'outro',
439	        observacao: nome,
440	        preco_unitario_esboco: valor,
441	        quantidade: 1,
442	        unidade: 'un',
443	        ordem: items.length,
444	      } as Record<string, unknown>);
445	      if (error) {
446	        toast.error(error.message);
447	        return;
448	      }
449	      toast.success('Custo avulso adicionado');
450	      await refetch();
451	    },
452	    [cmvId, items.length, refetch],
453	  );
454	
455	  if (loading || !cmv) {
456	    return (
457	      <div className="h-screen w-full flex items-center justify-center text-muted-foreground">
458	        <Loader2 className="animate-spin" />
459	      </div>
460	    );
461	  }
462	
463	  return (
464	    <div className="fixed inset-0 bg-zinc-50 dark:bg-zinc-950 font-sans">
465	      {/* Ambient glows */}
466	      <div className="fixed top-[-10%] left-[-10%] w-[500px] h-[500px] bg-[#57715B]/5 blur-[80px] rounded-full pointer-events-none" />
467	      <div className="fixed top-[20%] right-[-5%] w-[400px] h-[400px] bg-[#C5A065]/5 blur-[80px] rounded-full pointer-events-none" />
468	
469	      <ReactFlow
470	        nodes={nodes}
471	        edges={edges}
472	        nodeTypes={nodeTypes}
473	        onNodesChange={onNodesChange}
474	        onEdgesChange={onEdgesChange}
475	        onNodeDragStop={handleNodeDragStop}
476	        onNodeClick={handleNodeClick}
477	        onPaneClick={handlePaneClick}
478	        minZoom={0.2}
479	        maxZoom={3}
480	      >
481	        <Background variant={BackgroundVariant.Dots} color="#57715B" gap={24} className="opacity-20" />
482	        <MiniMap
483	          zoomable
484	          pannable
485	          nodeClassName={(n) => {
486	            if (n.type === 'cmv') return '!fill-[#57715B]';
487	            if (n.type === 'ficha') return '!fill-amber-500';
488	            if (n.type === 'cmvItem') {
489	              const d = n.data as CmvItemNodeData;
490	              return d.tipo === 'embalagem' ? '!fill-blue-500' : '!fill-orange-500';
491	            }
492	            if (n.type === 'nf') return '!fill-cyan-500';
493	            return '!fill-slate-500';
494	          }}
495	        />
496	
497	        {/* Back arrow + CMV name header */}
498	        <Panel position="top-left">
499	          <div className="flex items-center gap-2 bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl px-3 py-2 shadow-xl">
500	            <Button
501	              variant="ghost"
502	              size="icon"
503	              className="h-9 w-9"
504	              onClick={() => navigate('/financeiro/cmv')}
505	            >
506	              <ArrowLeft size={16} />
507	            </Button>
508	            <div className="w-px h-5 bg-[#57715B]/15" />
509	            <div className="flex items-center gap-2">
510	              <Calculator size={14} className="text-[#57715B]" />
511	              <span className="text-sm font-semibold truncate max-w-[180px]">{cmv.nome}</span>
512	              <span
513	                className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[cmv.status] ?? STATUS_COLORS.rascunho}`}
514	              >
515	                {cmv.status}
516	              </span>
517	            </div>
518	          </div>
519	        </Panel>
520	
521	        {/* Legend */}
522	        <Panel position="top-right">
523	          <div className="flex flex-col gap-1.5 bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl p-3 shadow-lg text-[10px] text-muted-foreground">
524	            <p className="text-[9px] font-bold uppercase tracking-widest mb-1 text-[#57715B]">
525	              Legenda
526	            </p>
527	            <div className="flex items-center gap-1.5">
528	              <Calculator size={10} className="text-[#57715B]" />
529	              <span>CMV Central</span>
530	            </div>
531	            <div className="flex items-center gap-1.5">
532	              <ChefHat size={10} className="text-amber-500" />
533	              <span>Ficha Técnica</span>
534	            </div>
535	            <div className="flex items-center gap-1.5">
536	              <Package size={10} className="text-blue-400" />
537	              <span>Embalagem</span>
538	            </div>
539	            <div className="flex items-center gap-1.5">
540	              <DollarSign size={10} className="text-orange-400" />
541	              <span>Custo avulso</span>
542	            </div>
543	            <div className="flex items-center gap-1.5">
544	              <Receipt size={10} className="text-cyan-400" />
545	              <span>Nota Fiscal</span>
546	            </div>
547	          </div>
548	        </Panel>
549	
550	        {/* Cost summary panel */}
551	        <Panel position="bottom-left">
552	          <div className="bg-white/90 dark:bg-slate-900/85 border border-[#57715B]/10 backdrop-blur-md rounded-xl p-4 shadow-2xl flex flex-col gap-3 min-w-[220px]">
553	            <div className="flex items-center justify-between text-xs">
554	              <span className="text-muted-foreground flex items-center gap-1.5">
555	                <ChefHat size={12} /> Ficha Base
556	              </span>
557	              <span className="font-semibold">{fmt(custoFichaUnitario)}</span>
558	            </div>
559	            <div className="flex items-center justify-between text-xs">
560	              <span className="text-muted-foreground flex items-center gap-1.5">
561	                <Package size={12} /> Embalagens
562	              </span>
563	              <span className="font-semibold">{fmt(custoEmbalagens)}</span>
564	            </div>
