1	import { useState, useEffect } from 'react';
2	import { Dialog, DialogContent } from '@/shared/ui/dialog';
3	import { Input } from '@/shared/ui/input';
4	import { Button } from '@/shared/ui/button';
5	import { Receipt, Search, ChevronRight, Loader2, Check } from 'lucide-react';
6	import { supabase } from '@/integrations/supabase/client';
7	import { toast } from 'sonner';
8	
9	interface CmvAtrelarNFDialogProps {
10	  open: boolean;
11	  cmvItemId: number | null;
12	  embalagemNome: string | null;
13	  currentNfItemId: number | null;
14	  onClose: () => void;
15	  onSaved: () => void;
16	}
17	
18	type NF = {
19	  id: number;
20	  fornecedor: string | null;
21	  numero_nota: string | null;
22	  valor_total: number | null;
23	  data_nota: string | null;
24	};
25	
26	type NFItem = {
27	  id: number;
28	  nota_id: number;
29	  nome_produto: string | null;
30	  quantidade: number | null;
31	  valor_unitario: number | null;
32	  subtotal: number | null;
33	  insumo_id: number | null;
34	};
35	
36	export function CmvAtrelarNFDialog({
37	  open,
38	  cmvItemId,
39	  embalagemNome,
40	  currentNfItemId,
41	  onClose,
42	  onSaved,
43	}: CmvAtrelarNFDialogProps) {
44	  const [step, setStep] = useState<'pickNF' | 'pickItem'>('pickNF');
45	  const [nfs, setNfs] = useState<NF[]>([]);
46	  const [nfItems, setNfItems] = useState<NFItem[]>([]);
47	  const [pickedNF, setPickedNF] = useState<NF | null>(null);
48	  const [busca, setBusca] = useState('');
49	  const [loading, setLoading] = useState(false);
50	  const [saving, setSaving] = useState(false);
51	
52	  useEffect(() => {
53	    if (open) {
54	      setStep('pickNF');
55	      setPickedNF(null);
56	      setBusca('');
57	      fetchNFs();
58	    }
59	    // fetchNFs is intentionally omitted — it's a stable async function defined in the same scope
60	    // eslint-disable-next-line react-hooks/exhaustive-deps
61	  }, [open]);
62	
63	  const fetchNFs = async () => {
64	    setLoading(true);
65	    const { data, error } = await supabase
66	      .from('notas_fiscais')
67	      .select('id, fornecedor, numero_nota, valor_total, data_nota')
68	      .order('data_nota', { ascending: false })
69	      .limit(80);
70	
71	    if (error) {
72	      toast.error('Erro ao buscar notas fiscais: ' + error.message);
73	    } else {
74	      setNfs((data ?? []) as NF[]);
75	    }
76	    setLoading(false);
77	  };
78	
79	  const fetchItems = async (nfId: number) => {
80	    setLoading(true);
81	    const { data, error } = await supabase
82	      .from('itens_nota_fiscal')
83	      .select('id, nota_id, nome_produto, quantidade, valor_unitario, subtotal, insumo_id')
84	      .eq('nota_id', nfId);
85	
86	    if (error) {
87	      toast.error('Erro ao buscar itens da nota: ' + error.message);
88	    } else {
89	      setNfItems((data ?? []) as NFItem[]);
90	    }
91	    setLoading(false);
92	  };
93	
94	  const handlePickNF = (nf: NF) => {
95	    setPickedNF(nf);
96	    setBusca('');
97	    setStep('pickItem');
98	    fetchItems(nf.id);
99	  };
100	
101	  const handlePickItem = async (item: NFItem) => {
102	    if (!cmvItemId) return;
103	    setSaving(true);
104	
105	    const { error } = await supabase
106	      .from('cmv_itens')
107	      .update({ nf_item_id: item.id, preco_unitario_esboco: null } as Record<string, unknown>)
108	      .eq('id', cmvItemId);
109	
110	    setSaving(false);
111	
112	    if (error) {
113	      toast.error('Erro ao atrelar NF: ' + error.message);
114	    } else {
115	      toast.success('Nota fiscal atrelada com sucesso');
116	      onSaved();
117	      onClose();
118	    }
119	  };
120	
121	  const filteredNFs = nfs.filter(
122	    (n) =>
123	      (n.fornecedor?.toLowerCase() ?? '').includes(busca.toLowerCase()) ||
124	      (n.numero_nota?.toLowerCase() ?? '').includes(busca.toLowerCase()),
125	  );
126	
127	  const filteredItems = nfItems.filter((i) =>
128	    (i.nome_produto?.toLowerCase() ?? '').includes(busca.toLowerCase()),
129	  );
130	
131	  const formatDate = (d: string | null) => {
132	    if (!d) return '';
133	    try {
134	      return new Date(d).toLocaleDateString('pt-BR');
135	    } catch {
136	      return d;
137	    }
138	  };
139	
140	  const formatMoney = (v: number | null) => {
141	    if (v === null) return 'R$ 0,00';
142	    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
143	  };
144	
145	  return (
146	    <Dialog open={open} onOpenChange={(val) => !val && onClose()}>
147	      <DialogContent className="max-w-2xl max-h-[82vh] flex flex-col bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl p-0 overflow-hidden">
148	        <div className="p-4 border-b border-[#57715B]/10 flex flex-col gap-2 shrink-0">
149	          <div className="flex items-center justify-between">
150	            <h2 className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
151	              Atrelar Nota Fiscal a {embalagemNome ?? 'Embalagem'}
152	            </h2>
153	          </div>
154	
155	          {step === 'pickItem' && pickedNF && (
156	            <div className="flex items-center gap-2 text-sm text-muted-foreground mt-1">
157	              <Button
158	                variant="ghost"
159	                size="sm"
160	                className="h-6 px-2 text-xs hover:bg-[#57715B]/10 text-[#57715B]"
161	                onClick={() => {
162	                  setStep('pickNF');
163	                  setBusca('');
164	                }}
165	              >
166	                Outra NF
167	              </Button>
168	              <ChevronRight size={14} />
169	              <span className="font-medium text-[#57715B]">
170	                NF {pickedNF.numero_nota} - {pickedNF.fornecedor}
171	              </span>
172	            </div>
173	          )}
174	
175	          <div className="relative mt-2">
176	            <Search
177	              className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground"
178	              size={16}
179	            />
180	            <Input
181	              value={busca}
182	              onChange={(e) => setBusca(e.target.value)}
183	              placeholder={
184	                step === 'pickNF'
185	                  ? 'Buscar por fornecedor ou número...'
186	                  : 'Buscar por produto na nota...'
187	              }
188	              className="pl-9 bg-white/60 dark:bg-black/20 border-[#57715B]/15 rounded-xl focus-visible:ring-[#57715B]/30"
189	            />
190	          </div>
191	        </div>
192	
193	        <div className="flex-1 overflow-y-auto p-2">
194	          {loading && (
195	            <div className="flex items-center justify-center p-8">
196	              <Loader2 className="animate-spin text-[#57715B]" size={24} />
197	            </div>
198	          )}
199	
200	          {!loading && step === 'pickNF' && (
201	            <div className="flex flex-col divide-y divide-[#57715B]/10">
202	              {filteredNFs.map((nf) => (
203	                <button
204	                  key={nf.id}
205	                  onClick={() => handlePickNF(nf)}
206	                  className="flex items-center justify-between p-3 text-left hover:bg-[#57715B]/5 transition-colors rounded-lg group"
207	                >
208	                  <div className="flex items-center gap-3">
209	                    <div className="p-2 bg-[#57715B]/10 rounded-lg text-[#57715B]">
210	                      <Receipt size={18} />
211	                    </div>
212	                    <div>
213	                      <div className="font-bold text-[#2D362E] dark:text-[#E6DCCF] group-hover:text-[#57715B] transition-colors">
214	                        {nf.fornecedor ?? 'Desconhecido'}
215	                      </div>
216	                      <div className="text-xs text-muted-foreground">
217	                        NF: {nf.numero_nota} • Data: {formatDate(nf.data_nota)}
218	                      </div>
219	                    </div>
220	                  </div>
221	                  <div className="font-medium tabular-nums text-[#57715B]">
222	                    {formatMoney(nf.valor_total)}
223	                  </div>
224	                </button>
225	              ))}
226	              {filteredNFs.length === 0 && (
227	                <div className="p-8 text-center text-muted-foreground text-sm">
228	                  Nenhuma nota fiscal encontrada.
229	                </div>
230	              )}
231	            </div>
232	          )}
233	
234	          {!loading && step === 'pickItem' && (
235	            <div className="flex flex-col gap-1">
236	              {filteredItems.map((item) => {
237	                const isAlreadyLinked = item.id === currentNfItemId;
238	
239	                return (
240	                  <button
241	                    key={item.id}
242	                    disabled={saving}
243	                    onClick={() => handlePickItem(item)}
244	                    className={`flex items-center justify-between p-3 text-left transition-colors rounded-xl ${
245	                      isAlreadyLinked
246	                        ? 'border-l-4 border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20'
247	                        : 'hover:bg-[#57715B]/5'
248	                    }`}
249	                  >
250	                    <div className="flex-1 pr-4">
251	                      <div className="font-medium text-[#2D362E] dark:text-[#E6DCCF] flex items-center gap-2">
252	                        {item.nome_produto}
253	                        {isAlreadyLinked && <Check size={14} className="text-emerald-600" />}
254	                      </div>
255	                      <div className="text-xs text-muted-foreground mt-1">
256	                        {item.quantidade} un × {formatMoney(item.valor_unitario)}
257	                      </div>
258	                    </div>
259	                    <div className="font-bold text-[#57715B] tabular-nums whitespace-nowrap">
260	                      {formatMoney(item.subtotal ?? (item.quantidade ?? 0) * (item.valor_unitario ?? 0))}
261	                    </div>
262	                  </button>
263	                );
264	              })}
265	              {filteredItems.length === 0 && (
266	                <div className="p-8 text-center text-muted-foreground text-sm">
267	                  Nenhum item encontrado nesta nota.
268	                </div>
269	              )}
270	            </div>
271	          )}
272	        </div>
273	      </DialogContent>
274	    </Dialog>
275	  );
276	}
