114	export const cmvNodeId = (id: number) => `cmv_${id}`;
115	export const fichaNodeId = (id: number) => `ficha_${id}`;
116	export const insumoNodeId = (id: number) => `insumo_${id}`;
117	export const nfNodeId = (id: number) => `nf_${id}`;
118	
119	export const parseNodeId = (key: string): { type: CmvNodeKind; id: number } | null => {
120	  const idx = key.indexOf('_');
121	  if (idx < 0) return null;
122	  const typeStr = key.slice(0, idx);
123	  const id = Number(key.slice(idx + 1));
124	  if (!Number.isFinite(id)) return null;
125	  const validTypes: CmvNodeKind[] = ['cmv', 'ficha', 'insumo', 'nf', 'item'];
126	  if (validTypes.includes(typeStr as CmvNodeKind)) {
127	    return { type: typeStr as CmvNodeKind, id };
128	  }
129	  return null;
130	};
131	
132	export interface CmvGraphData {
133	  loading: boolean;
134	  cmv: RawCmv | null;
135	  fichaData: RawCmvFicha | null;
136	  items: RawCmvItem[];
137	  insumos: RawCmvInsumo[];
138	  /** Catálogo de produtos do setor EMBALAGENS para o seletor de embalagem */
139	  embalagens: RawCmvEmbalagem[];
140	  /** Itens de NF filtrados por categoria='Embalagens' para atrelar custo */
141	  nfEmbalagemItems: NfEmbalagemItem[];
142	  /** Notas fiscais gerais (retrocompat) */
143	  notas: RawCmvNF[];
144	  /** Itens de NF vinculados a insumos (retrocompat) */
145	  nfItems: RawCmvNFItem[];
146	  positions: Map<string, { x: number; y: number }>;
147	  savePosition: (key: string, x: number, y: number) => Promise<void>;
148	  refetch: () => Promise<void>;
149	}
