67	      return;
68	    }
69	    setLoading(true);
70	    (async () => {
71	      // Se forceNFId: skipa step1, carrega só essa NF + seus itens
72	      if (forceNFId != null) {
73	        const { data: nfData } = await supabase
74	          .from('notas_fiscais')
75	          .select('id, fornecedor, numero_nota, valor_total, data_nota')
76	          .eq('id', forceNFId)
77	          .single();
78	        if (nfData) {
79	          const nfPicked = nfData as NF;
80	          setPickedNF(nfPicked);
81	          setStep('pickItem');
82	          const { data: itensData } = await supabase
