84	            .select('id, nota_id, nome_produto, quantidade, valor_unitario, subtotal, insumo_id')
85	            .eq('nota_id', forceNFId)
86	            .order('id');
87	          setItems((itensData ?? []) as NFItem[]);
88	        }
89	        setLoading(false);
90	        return;
91	      }
92	      // Fluxo normal: lista NFs recentes pra busca
93	      const { data } = await supabase
94	        .from('notas_fiscais')
95	        .select('id, fornecedor, numero_nota, valor_total, data_nota')
96	        .order('data_nota', { ascending: false })
97	        .limit(80);
